/// Foreground / background / indicator triple for tonal badges (status, trust, KYC).
@immutable
class JkTone {
  const JkTone({required this.fg, required this.bg, required this.dot});
  final Color fg;
  final Color bg;
  final Color dot;

  static JkTone lerp(JkTone a, JkTone b, double t) => JkTone(
        fg: Color.lerp(a.fg, b.fg, t)!,
        bg: Color.lerp(a.bg, b.bg, t)!,
        dot: Color.lerp(a.dot, b.dot, t)!,
      );
}

