      onEstimateBadge: onEstimateBadge ?? this.onEstimateBadge,
      status: status ?? this.status,
      trust: trust ?? this.trust,
      kyc: kyc ?? this.kyc,
    );
  }

  static Map<String, JkTone> _lerpTones(Map<String, JkTone> a, Map<String, JkTone> b, double t) =>
      <String, JkTone>{for (final k in a.keys) k: JkTone.lerp(a[k]!, b[k] ?? a[k]!, t)};

  @override
  JkColors lerp(ThemeExtension<JkColors>? other, double t) {
    if (other is! JkColors) return this;
    return JkColors(
      brightness: t < 0.5 ? brightness : other.brightness,
      background: Color.lerp(background, other.background, t)!,
      onBackground: Color.lerp(onBackground, other.onBackground, t)!,
      onBackgroundMuted: Color.lerp(onBackgroundMuted, other.onBackgroundMuted, t)!,
      surface: Color.lerp(surface, other.surface, t)!,
      surfaceMuted: Color.lerp(surfaceMuted, other.surfaceMuted, t)!,
      surfaceElevated: Color.lerp(surfaceElevated, other.surfaceElevated, t)!,
      surfaceGlass: Color.lerp(surfaceGlass, other.surfaceGlass, t)!,
      onGlass: Color.lerp(onGlass, other.onGlass, t)!,
      onGlassMuted: Color.lerp(onGlassMuted, other.onGlassMuted, t)!,
      onGlassActive: Color.lerp(onGlassActive, other.onGlassActive, t)!,
      surfaceInverse: Color.lerp(surfaceInverse, other.surfaceInverse, t)!,
      onSurface: Color.lerp(onSurface, other.onSurface, t)!,
      onSurfaceMuted: Color.lerp(onSurfaceMuted, other.onSurfaceMuted, t)!,
      onSurfaceInverse: Color.lerp(onSurfaceInverse, other.onSurfaceInverse, t)!,
      primary: Color.lerp(primary, other.primary, t)!,
      onPrimary: Color.lerp(onPrimary, other.onPrimary, t)!,
      primaryContainer: Color.lerp(primaryContainer, other.primaryContainer, t)!,
      onPrimaryContainer: Color.lerp(onPrimaryContainer, other.onPrimaryContainer, t)!,
      secondary: Color.lerp(secondary, other.secondary, t)!,
      onSecondary: Color.lerp(onSecondary, other.onSecondary, t)!,
      secondaryContainer: Color.lerp(secondaryContainer, other.secondaryContainer, t)!,
      onSecondaryContainer: Color.lerp(onSecondaryContainer, other.onSecondaryContainer, t)!,
      cta: Color.lerp(cta, other.cta, t)!,
      ctaPressed: Color.lerp(ctaPressed, other.ctaPressed, t)!,
      onCta: Color.lerp(onCta, other.onCta, t)!,
      link: Color.lerp(link, other.link, t)!,
      border: Color.lerp(border, other.border, t)!,
      outline: Color.lerp(outline, other.outline, t)!,
      divider: Color.lerp(divider, other.divider, t)!,
      focusRing: Color.lerp(focusRing, other.focusRing, t)!,
      scrim: Color.lerp(scrim, other.scrim, t)!,
      disabledContent: Color.lerp(disabledContent, other.disabledContent, t)!,
      disabledContainer: Color.lerp(disabledContainer, other.disabledContainer, t)!,
      glassBorder: Color.lerp(glassBorder, other.glassBorder, t)!,
      glassShadow: Color.lerp(glassShadow, other.glassShadow, t)!,
      success: Color.lerp(success, other.success, t)!,
      onSuccess: Color.lerp(onSuccess, other.onSuccess, t)!,
      successContainer: Color.lerp(successContainer, other.successContainer, t)!,
      onSuccessContainer: Color.lerp(onSuccessContainer, other.onSuccessContainer, t)!,
      successText: Color.lerp(successText, other.successText, t)!,
      warning: Color.lerp(warning, other.warning, t)!,
      onWarning: Color.lerp(onWarning, other.onWarning, t)!,
      warningContainer: Color.lerp(warningContainer, other.warningContainer, t)!,
      onWarningContainer: Color.lerp(onWarningContainer, other.onWarningContainer, t)!,
      warningText: Color.lerp(warningText, other.warningText, t)!,
      error: Color.lerp(error, other.error, t)!,
      onError: Color.lerp(onError, other.onError, t)!,
      errorContainer: Color.lerp(errorContainer, other.errorContainer, t)!,
      onErrorContainer: Color.lerp(onErrorContainer, other.onErrorContainer, t)!,
      errorText: Color.lerp(errorText, other.errorText, t)!,
      info: Color.lerp(info, other.info, t)!,
      onInfo: Color.lerp(onInfo, other.onInfo, t)!,
      infoContainer: Color.lerp(infoContainer, other.infoContainer, t)!,
      onInfoContainer: Color.lerp(onInfoContainer, other.onInfoContainer, t)!,
      infoText: Color.lerp(infoText, other.infoText, t)!,
      safepaySecured: Color.lerp(safepaySecured, other.safepaySecured, t)!,
      onSafepaySecured: Color.lerp(onSafepaySecured, other.onSafepaySecured, t)!,
      safepayBlocked: Color.lerp(safepayBlocked, other.safepayBlocked, t)!,
      onSafepayBlocked: Color.lerp(onSafepayBlocked, other.onSafepayBlocked, t)!,
      safepayPending: Color.lerp(safepayPending, other.safepayPending, t)!,
      onSafepayPending: Color.lerp(onSafepayPending, other.onSafepayPending, t)!,
      estimateBadge: Color.lerp(estimateBadge, other.estimateBadge, t)!,
