/// Transaction status → colour group, trust score → tier (mirrors docs/00-domain-model.md).
abstract final class JkStatus {
  static const Map<String, String> transactionStatusGroup = <String, String>{
    'REQUEST_CREATED': 'open',
    'MATCHED': 'open',
    'AWAITING_PAYMENT': 'actionRequired',
    'PRICE_CHANGE_PENDING': 'actionRequired',
    'PAYMENT_SECURED': 'secured',
    'PURCHASE_APPROVED': 'secured',
    'PURCHASED': 'inTransit',
    'TRAVELING': 'inTransit',
    'ARRIVED': 'inTransit',
    'CUSTOMS_PROCESS': 'inTransit',
    'READY_FOR_HANDOVER': 'inTransit',
    'OUT_FOR_DELIVERY': 'inTransit',
    'DELIVERED': 'delivered',
    'BUYER_CONFIRMED': 'delivered',
    'COMPLETED': 'completed',
    'DISPUTED': 'disputed',
    'REFUND_PENDING': 'refund',
    'REFUNDED': 'closed',
    'CANCELLED': 'closed',
  };

  static String groupOf(String transactionStatus) => transactionStatusGroup[transactionStatus] ?? 'closed';

  static String trustTierOf(int score) {
    final s = score.clamp(0, 100);
    if (s >= 0 && s <= 39) return 'low';
    if (s >= 40 && s <= 69) return 'fair';
    if (s >= 70 && s <= 84) return 'good';
    if (s >= 85 && s <= 100) return 'excellent';
    return 'low';
  }
}

