/// Durations & curves. Always check `MediaQuery.disableAnimationsOf(context)`: when true use
/// a cross-fade of at most [reducedCrossfade] instead of spatial motion.
abstract final class JkMotion {
  static const Duration instant = Duration(milliseconds: 0);
  static const Duration fast = Duration(milliseconds: 120);
  static const Duration base = Duration(milliseconds: 200);
  static const Duration slow = Duration(milliseconds: 300);
  static const Duration emphasized = Duration(milliseconds: 450);
  static const Duration reducedCrossfade = Duration(milliseconds: 120);
  static const Cubic standard = Cubic(0.2, 0.0, 0.0, 1.0);
  static const Cubic standardDecelerate = Cubic(0.0, 0.0, 0.0, 1.0);
  static const Cubic standardAccelerate = Cubic(0.3, 0.0, 1.0, 1.0);
  static const Cubic emphasizedDecelerate = Cubic(0.05, 0.7, 0.1, 1.0);
  static const Cubic emphasizedAccelerate = Cubic(0.3, 0.0, 0.8, 0.15);
  static final SpringDescription fastSpatialSpring = SpringDescription.withDampingRatio(mass: 1.0, stiffness: 1400.0, ratio: 0.9);
  static final SpringDescription defaultSpatialSpring = SpringDescription.withDampingRatio(mass: 1.0, stiffness: 700.0, ratio: 0.9);
  static final SpringDescription expressiveSpatialSpring = SpringDescription.withDampingRatio(mass: 1.0, stiffness: 380.0, ratio: 0.8);
  static final SpringDescription defaultEffectsSpring = SpringDescription.withDampingRatio(mass: 1.0, stiffness: 1600.0, ratio: 1.0);
}

